"use strict";(globalThis.webpackChunkgrc||=[]).push([[70049],{31218(e){e.exports=JSON.parse('{"citeKey":"gurbani2003accessingtelephony","slug":"gurbani-2003-accessing-telephony-c8bf","title":"Accessing telephony services from the Internet","authors":["V. K. Gurbani","X.-H. Sun"],"venue":"The IEEE International Conference on Computer Communications and Networks} (ICCCN03), Dallars, TX.","type":"Conference","entryType":"inproceedings","date":"October, 2003","year":2003,"era":"iit","month":10,"doi":"10.1109/icccn.2003.1284218","abstract":"Networks exist to provide services to users. Increasingly, the networks on which the services reside are not the same as the networks from which the services are accessed. This leads to the problem on how to best provide such services transparently when the access protocols differ. We discusses a methodology to make available the existing services residing in a network whose protocols are distinct from the network where the access attempt is made. We propose a technique we term call model mapping with state sharing and demonstrate it in the telecommunication domain where we access traditional telephony services residing on the telephone network from Internet telephony endpoints residing on the Internet.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2003/gurbani-2003-accessing-telephony-c8bf.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);